import importlib, pkgutil
for m in ['seisbench','obspy','scipy','numpy','pandas']:
    try:
        mod=importlib.import_module(m)
        print(m,'OK',getattr(mod,'__version__', 'no_version'))
    except Exception as e:
        print(m,'FAIL',e)
